#include <cublas_v2.h>
#include <cuda_runtime.h>
#include <stdio.h>

#define CUBLAS_CHECK(call) { cublasStatus_t err = call; if (err != CUBLAS_STATUS_SUCCESS) { fprintf(stderr, "cuBLAS error %d at %s:%d\n", err, __FILE__, __LINE__); exit(1); } }
#define CUDA_CHECK(call) { cudaError_t err = call; if (err != cudaSuccess) { fprintf(stderr, "CUDA error: %s at %s:%d\n", cudaGetErrorString(err), __FILE__, __LINE__); exit(1); } }

// One-time init — cache these for the lifetime of the process
static cublasHandle_t g_cublas = nullptr;
void ensure_cublas() {
    if (!g_cublas) {
        CUBLAS_CHECK(cublasCreate(&g_cublas));
        CUBLAS_CHECK(cublasSetMathMode(g_cublas, CUBLAS_TENSOR_OP_MATH));
    }
}

// GEMM wrapper: C = alpha * A * B + beta * C
void gpu_sgemm(const float* A, const float* B, float* C,
               int m, int n, int k, float alpha, float beta) {
    ensure_cublas();
    CUBLAS_CHECK(cublasSgemm(g_cublas, CUBLAS_OP_N, CUBLAS_OP_N,
                             n, m, k,  // note: column-major order
                             &alpha, B, n, A, k, &beta, C, n));
}
